// SpringApplication.run 核心伪代码（基于 Spring Boot 3.x 源码结构）
public ConfigurableApplicationContext run(String... args) {
    StopWatch stopWatch = new StopWatch();
    stopWatch.start();

    // 1. 获取 RunListeners（SPI: spring.factories 的 SpringApplicationRunListener）
    SpringApplicationRunListeners listeners = getRunListeners(args);
    listeners.starting();

    // 2. 准备 Environment
    ApplicationEnvironment environment = prepareEnvironment(listeners);
    //    加载配置源、激活 Profile、发布 ApplicationEnvironmentPreparedEvent

    // 3. 创建 ApplicationContext
    //    SERVLET → AnnotationConfigServletWebServerApplicationContext
    //    REACTIVE → AnnotationConfigReactiveWebServerApplicationContext
    //    NONE → AnnotationConfigApplicationContext
    ConfigurableApplicationContext context = createApplicationContext();

    // 4. 准备容器
    prepareContext(context, environment, listeners, applicationArguments);
    //    执行 ApplicationContextInitializer.initialize()
    //    加载主配置类（@SpringBootApplication 标注的类）
    //    发布 ApplicationPreparedEvent

    // 5. 刷新容器（核心，耗时最长）
    refreshContext(context);
    //    → AbstractApplicationContext.refresh()
    //    → invokeBeanFactoryPostProcessors: 解析 @Configuration、@EnableAutoConfiguration
    //    → ConfigurationClassPostProcessor → AutoConfigurationImportSelector
    //    → 读取 AutoConfiguration.imports → @Conditional 过滤 → 注册 BeanDefinition
    //    → registerBeanPostProcessors
    //    → finishBeanFactoryInitialization: 实例化非懒加载单例 Bean
    //    → onRefresh: 创建并启动内嵌 WebServer（Tomcat）

    // 6. 刷新后处理
    afterRefresh(context);
    stopWatch.stop();
    listeners.started(context);

    // 7. 执行 Runner
    callRunners(context, applicationArguments);
    //    按 @Order 排序执行 ApplicationRunner 和 CommandLineRunner
    listeners.running(context);

    return context;
}
